import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.DwAI3uWn.js";const m=JSON.parse('{"title":"Technical requirements — Chainy","description":"Version 0.1 • October 8, 2026 • Proposed implementation contract, not implementation evidence.","frontmatter":{"title":"Technical requirements — Chainy","description":"Version 0.1 • October 8, 2026 • Proposed implementation contract, not implementation evidence.","source":"docs/requirements/technical-requirements.md","category":"Requirements","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/technical-requirements.md","filePath":"content/docs/requirements/technical-requirements.md"}'),i={name:"content/docs/requirements/technical-requirements.md"};function o(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<div><h1 id="technical-requirements--chainy">Technical requirements — Chainy<a class="header-anchor" href="#technical-requirements--chainy" aria-label="Link to this section">​</a></h1><p>Version 0.1 • October 8, 2026 • Proposed implementation contract, not implementation evidence.</p><p>Read the <a href="/Chainy-Docs/content/docs/project-baseline.html">confirmed baseline</a>, <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a>, <a href="/Chainy-Docs/content/docs/technical-design.html">architecture overview</a>, <a href="/Chainy-Docs/content/docs/design/app-flow.html">app flow</a>, and <a href="/Chainy-Docs/content/docs/design/database-schema.html">database contract</a> together. CH-R IDs refer to confirmed requirements; TR IDs below describe proposed engineering acceptance contracts. The November 21, 2026 pre-final requires functional core modules, complete manuscript chapters and actual pilot evidence; passing technical checks alone does not establish the school&#39;s 60-percent completion threshold.</p><h2 id="runtime-and-repository-boundaries">Runtime and repository boundaries<a class="header-anchor" href="#runtime-and-repository-boundaries" aria-label="Link to this section">​</a></h2><p>The management repository contains requirements, decisions, synthetic fixtures and publication inventory. Production Unity/C# code, Unity metadata, packaged content, tests and build configuration belong in <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>. Never store participant exports, identity maps or signing keys in either repository.</p><p>The game is single-player, touchscreen-controlled and fully playable offline. Unity renders exploration and activities; deterministic C# services implement learning rules; SQLite is the authoritative local store. Bundled content supplies instructions, lessons and quizzes. An Android export adapter writes teacher-selected evidence files. A separate staff-operated importer aggregates those files. The existing GitHub–Trello management integration is outside the game runtime and must not become a gameplay dependency.</p><table><thead><tr><th>Selection</th><th>Decision status and owner</th><th>Exit evidence</th></tr></thead><tbody><tr><td>Unity/C# and Android</td><td>Confirmed direction; Christian owns build setup</td><td>Pinned editor patch, SDK/NDK/JDK versions, render pipeline and build instructions in game repo</td></tr><tr><td>SQLite binding</td><td>Unselected; Christian, CH-04</td><td>License recorded; native ARM64 libraries included; transactions, foreign keys and signed-update migration verified on device</td></tr><tr><td>Graphics/device support</td><td>Android 11+ recommended; Android 10 test candidate</td><td>Actual API, device and measured workload recorded; no untested compatibility promise</td></tr><tr><td>Export adapter</td><td>Android system document picker recommended</td><td>Save, cancel, denied/unavailable destination and retry verified offline</td></tr><tr><td>Classifier</td><td>Local nearest-centroid recommended; Sherwin</td><td>Synthetic examples demonstrate changed predictions after retraining, missing-class and tie behavior</td></tr><tr><td>Research importer</td><td>Small staff-operated command-line tool and CSV summary recommended</td><td>Repeat import changes no totals; conflicts are quarantined; approved custodian can operate it</td></tr></tbody></table><p>Do not select package versions from an old design document. CH-03/04 must verify current official vendor documentation for the versions actually selected and commit dependency locks. No package, binding, target device or production build is asserted as tested here.</p><h2 id="system-boundaries-and-interfaces">System boundaries and interfaces<a class="header-anchor" href="#system-boundaries-and-interfaces" aria-label="Link to this section">​</a></h2><p>The following contracts describe behavior; exact C# names are proposed and may change without changing semantics. Use plain data objects at module boundaries, stable string content IDs and explicit error codes. One integration owner controls shared contracts and scene composition.</p><table><thead><tr><th>Boundary</th><th>Input → output</th><th>Invariants and failure contract</th></tr></thead><tbody><tr><td>Bootstrap/content loader</td><td>Packaged content + database version → readiness result</td><td>Reject unsupported schema/content; preserve old data; expose recovery instead of entering gameplay</td></tr><tr><td>Profile service</td><td>Study ID + normalized learner code → local profile key</td><td>No authentication claim; new code requires new-profile confirmation; no cross-device restore</td></tr><tr><td>Mission service</td><td>Profile + activity definition + checkpoint → mission state</td><td>Unlock derives from persisted completion; missing/incompatible checkpoint restarts safely with explanation</td></tr><tr><td>Construction service</td><td>Component catalog + edit command → graph snapshot or validation errors</td><td>Logical graph independent of visual positions; fixed object bound; legal IDs/ports and finite coordinates</td></tr><tr><td>Ledger rules</td><td>Canonical ordered records + expected reference → validation result</td><td>Same input produces same result; distinguish order, predecessor, digest and reference disagreement</td></tr><tr><td>Replica rules</td><td>Three local copies + explicit trusted reference → agreement/repair preview</td><td>Two matching valid copies only under scenario assumptions; all-different reports no agreement</td></tr><tr><td>Classifier</td><td>Labeled feature vectors → model; model + held-out item → prediction</td><td>Numeric feature order/scale versioned; missing classes and ties explicit; no fabricated confidence</td></tr><tr><td>Agent rules</td><td>Environment + visible policy + step limit → action trace/result</td><td>Deterministic update order; illegal action and step limit return explained failure, never an endless loop</td></tr><tr><td>Evidence/persistence</td><td>Stable event + selected profile/session context → committed outcome</td><td>One transaction; duplicate identical event is idempotent; conflicting event never overwrites history</td></tr><tr><td>Export service</td><td>Approved scope → fixed manifest and selected records</td><td>Consistent snapshot; include interpretation dependencies; preserve local evidence after every result</td></tr><tr><td>Importer</td><td>Versioned package → accepted/duplicate/rejected counts + receipt</td><td>Validate first; global event IDs deduplicate; conflicting IDs quarantined; no device progress sync</td></tr></tbody></table><p>Recommended game folders: <code>Assets/Chainy/Runtime/{Core,Gameplay,Learning,Persistence,UI,Platform}</code>, plus <code>Content</code>, <code>Art</code>, <code>Audio</code>, <code>Scenes</code> and <code>Tests</code>. Define modules before splitting work; each agent owns separate files/prefabs and returns a bounded change with verification evidence. Avoid concurrent edits to the same Unity scene or central contract file.</p><h2 id="functional-acceptance-contracts">Functional acceptance contracts<a class="header-anchor" href="#functional-acceptance-contracts" aria-label="Link to this section">​</a></h2><table><thead><tr><th>ID</th><th>Requirement</th><th>Observable acceptance check</th><th>Trace / initial task</th></tr></thead><tbody><tr><td>TR-01</td><td>Boot and complete packaged play with network unavailable</td><td>Fresh installed test build starts and completes an activity in airplane mode, with no required online assets</td><td>CH-R01 / CH-03</td></tr><tr><td>TR-02</td><td>Movement, interaction and construction are separate modes</td><td>Touch movement cannot unintentionally place components; place, configure, connect, remove, undo and reset work; two spatially different valid layouts pass</td><td>CH-R02 / CH-05</td></tr><tr><td>TR-03</td><td>Version canonical record serialization and digest rules</td><td>Published synthetic fixtures produce repeatable digests; altered payload/broken predecessor/order each returns its own feedback</td><td>CH-R03,04 / CH-06,07</td></tr><tr><td>TR-04</td><td>Simulate three nodes entirely on one device</td><td>Agreement, one changed copy, repair and all-different cases are demonstrated; no secure-consensus or network claim</td><td>CH-R05 / CH-07</td></tr><tr><td>TR-05</td><td>Train and evaluate an actual small example-based model</td><td>Training and held-out sets are separate; changing examples changes a prediction in a fixture; tie and missing-class cases explained</td><td>CH-R06 / CH-08</td></tr><tr><td>TR-06</td><td>Run a bounded visible action policy</td><td>Learner policy change changes route result; trace explains action; loop/invalid action terminates at configured bound</td><td>CH-R07 / CH-09</td></tr><tr><td>TR-07</td><td>Persist feedback, first attempts, retries and completion correctly</td><td>Quiz retry appends a new attempt; repeated delivery of the same submission creates one event; unlock/badge appears only after commit</td><td>CH-R08,09 / CH-06,26</td></tr><tr><td>TR-08</td><td>Isolate shared-device profiles and recover interruption</td><td>Two codes maintain separate checkpoints; process termination/relaunch preserves committed records and interrupts previous session</td><td>CH-R09 / CH-04</td></tr><tr><td>TR-09</td><td>Export consistent pseudonymous evidence</td><td>Package contains versions and parent records, passes importer validation, and cancel/write failure does not delete records</td><td>CH-R10 / CH-04,11</td></tr><tr><td>TR-10</td><td>Preserve data through supported signed update</td><td>Existing synthetic profiles/attempts survive actual APK update; failed migration preserves recovery copy</td><td>CH-R11 / CH-14</td></tr><tr><td>TR-11</td><td>Make learning feedback readable and operable</td><td>Text accompanies colors/audio, touch alternatives support precise placement, locked/invalid states explain next action</td><td>CH-R01,08 / CH-10,26</td></tr><tr><td>TR-12</td><td>Build reproducibly and identify evidence</td><td>Commit, app/content/schema/instrument versions, device and test outcome accompany every release candidate</td><td>CH-R12 / CH-03,14,17</td></tr></tbody></table><h2 id="data-transactions-and-lifecycle">Data, transactions and lifecycle<a class="header-anchor" href="#data-transactions-and-lifecycle" aria-label="Link to this section">​</a></h2><p>Use <a href="/Chainy-Docs/content/docs/design/database-schema.html">the schema contract</a> and <a href="/Chainy-Docs/attachments/docs/design/local-schema.sql">executable proposed v1 SQL</a>. Each connection enables foreign keys before transactions. Use bound parameters, a single writer queue and short transactions. Callers receive typed outcomes such as <code>Committed</code>, <code>BusyRetryable</code>, <code>StorageFull</code>, <code>UnsupportedVersion</code>, <code>InvalidPayload</code> or <code>ConflictingEvent</code>; no success UI before commit.</p><p>Save meaningful activity results and safe checkpoints, not every frame. A result and resulting progress change commit together. Keep the generated event ID across retry after a failed/uncertain commit. On replay, compare existing content before treating the operation as already completed. Do not roll back newer progress when an old event is retried.</p><p>Suspend is a best-effort checkpoint opportunity; process termination can skip lifecycle callbacks. Checkpoint regularly after meaningful actions. At bootstrap mark sessions still active from the previous process as interrupted, retaining their attempts; a resumed activity starts a new session. Cross-device timestamps are contextual, not an ordering source.</p><h2 id="proposed-performance-and-scope-budgets">Proposed performance and scope budgets<a class="header-anchor" href="#proposed-performance-and-scope-budgets" aria-label="Link to this section">​</a></h2><p>These are targets from <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware validation</a>, not measured results: 30 FPS sustained; p95 frame time ≤40 ms; total process PSS ≤800 MiB on the candidate 4 GB phone; APK ≤500 MB; cold start ≤15 seconds; ordinary scene transition ≤8 seconds. Record installed size separately. Start with the GDD&#39;s proposed 12-object workbench cap, three replica nodes, two classifier classes and one short agent route. Measure the worst representative workload for at least 15 minutes and a full learner session for thermal/battery behavior.</p><p>Do not translate total device storage into application space requirements. Reduce decorative assets/effects before required learning behavior. Record save/submit latency and stalls during the device spike; no unsupported numeric latency guarantee is invented here.</p><h2 id="security-research-and-operations-boundaries">Security, research and operations boundaries<a class="header-anchor" href="#security-research-and-operations-boundaries" aria-label="Link to this section">​</a></h2><p>Learner codes identify offline profiles; teachers handle issuance and supervised selection. Do not describe code entry as secure login. Avoid names, unrestricted text, recordings and identity maps. Ordinary SQLite does not itself provide encryption. Define device custody, Android backup behavior, transfer destination, retention/deletion and access protections with the research lead before real collection. A hidden staff screen or convenience PIN is not strong authentication.</p><p>Export is a logical data snapshot; physical transfer and importer receipt are separate. Internet availability does not trigger upload, synchronization or updates. Signing credentials have a named custodian outside source control. Test update continuity before distribution; an uninstall can remove app-private data, so reinstall is not a recovery plan.</p><h2 id="verification-and-unresolved-gates">Verification and unresolved gates<a class="header-anchor" href="#verification-and-unresolved-gates" aria-label="Link to this section">​</a></h2><p>Pure rule tests cover ledger/order/replica cases, classifier edge cases and bounded agent behavior. Persistence tests cover foreign keys, two-profile isolation, atomic completion, duplicate/conflicting events, checkpoint compatibility and migration rollback. Import tests use synthetic packages for repeat imports, broken references, tampering, unsupported versions and receipt counts. Device checks cover touch, airplane mode, suspend/termination, disk/export failure where reproducible, sustained performance and signed update.</p><p>CH-03/04 must close the toolchain/binding/device choices by the October 9–11 spike targets or trigger reforecasting. CH-12/23/24 must resolve the actual instruments, custodian, permissions and booked pilot sessions; documentation cannot replace them. The October 8 conditional forecast replaces the November 6 integration target with an October 30 integrated beta candidate and October 31–November 2 readiness checks, ahead of the tentative November 3–6 Tambunan National High School beta. November 7–13 is reserved for regression, fixes and analysis; November 17–20 remains rehearsal and critical recovery time. Follow the current <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">implementation plan</a>, not the superseded target. Named Lead/Support/Reviewer and issue acceptance evidence govern execution; agent output alone does not close a task.</p><p>Parallel work ownership, contract gates and review packets are defined in the <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">implementation plan</a>.</p></div>',1)])])}const u=t(i,[["render",o]]);export{m as __pageData,u as default};
